export const getBarrierSequenceContent = (locale = "en") => {
  const key = content[locale] ? locale : "en";
  return { ...content[key], description: metaDescriptions[key] };
};

export const getBarrierSequenceUi = (locale = "en") => BARRIER_SEQUENCE_PURSUIT_I18N[locale] || BARRIER_SEQUENCE_PURSUIT_I18N.en;

export function buildBarrierSequenceSeo(locale, url, languages) {
  const d = getBarrierSequenceContent(locale);
  const faqSchema = {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: d.faqs.slice(0, 10).map(({ q, a }) => ({ "@type": "Question", name: q, acceptedAnswer: { "@type": "Answer", text: a } })),
  };
  const breadcrumbSchema = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: "https://skilldrills.online" },
      { "@type": "ListItem", position: 2, name: "Drills", item: `${url.split("/drills/")[0]}/drills` },
      { "@type": "ListItem", position: 3, name: "Reaction Speed", item: `${url.split("/reaction-speed/")[0]}/drills/reaction-speed` },
      { "@type": "ListItem", position: 4, name: d.title, item: url },
    ],
  };
  const softwareApplicationSchema = {
    "@context": "https://schema.org", "@type": "SoftwareApplication", name: d.title,
    alternateName: d.subtitle, applicationCategory: "GameApplication", operatingSystem: "All",
    offers: { "@type": "Offer", price: "0", priceCurrency: "USD" }, description: d.description,
    url, publisher: { "@type": "Organization", name: "SkillDrills", url: "https://skilldrills.online" },
    inLanguage: d.language, dateModified: "2026-09-20", sameAs: ["https://en.wikipedia.org/wiki/First-person_shooter", "https://en.wikipedia.org/wiki/Reaction_time"],
  };
  const webApplicationSchema = {
    "@context": "https://schema.org", "@type": "WebApplication", name: d.title,
    applicationCategory: "GameApplication", operatingSystem: "All", browserRequirements: "HTML5 Canvas and a modern web browser",
    offers: { "@type": "Offer", price: "0", priceCurrency: "USD" }, url, inLanguage: d.language, dateModified: "2026-09-20",
  };
  const videoGameSchema = {
    "@context": "https://schema.org", "@type": "VideoGame", name: d.title, url, description: d.description,
    genre: ["Aim training", "Tactical FPS", "Reaction training"], gamePlatform: ["Web Browser", "Desktop"],
    applicationCategory: "Game", offers: { "@type": "Offer", price: "0", priceCurrency: "USD" }, inLanguage: d.language,
  };
  const howToSchema = {
    "@context": "https://schema.org", "@type": "HowTo", name: d.introTitle, description: d.description,
    step: d.protocols.map((step, i) => ({ "@type": "HowToStep", position: i + 1, name: step.title, text: step.description, url: `${url}#step-${i + 1}` })),
  };
  return {
    metadata: {
      title: `${d.title} | SkillDrills`, description: d.description, keywords: d.keywords,
      openGraph: { title: `${d.title} | SkillDrills`, description: d.description, type: "article", url, siteName: "SkillDrills", locale: d.locale },
      twitter: { card: "summary_large_image", title: `${d.title} | SkillDrills`, description: d.description },
      robots: { index: true, follow: true }, alternates: { canonical: url, languages },
    },
    breadcrumbSchema, softwareApplicationSchema, webApplicationSchema, videoGameSchema, faqSchema, howToSchema,
  };
}

export function buildBarrierSequenceGuide(locale, sources) {
  const d = getBarrierSequenceContent(locale);
  return {
    sources,
    intro: { title: d.introTitle, paragraphs: d.intro },
    benchmarks: d.benchmarks,
    protocols: { title: locale === "ja" ? "4段階の練習プロトコル" : locale === "ko" ? "4단계 훈련 프로토콜" : locale === "de" ? "4-Phasen-Trainingsprotokoll" : locale === "pt" ? "Protocolo de treino em 4 fases" : locale === "es" ? "Protocolo de entrenamiento en 4 fases" : locale === "fr" ? "Protocole d'entraînement en 4 phases" : "Four-phase training protocol", description: d.description, items: d.protocols },
    faqs: { title: locale === "ja" ? "よくある質問" : locale === "ko" ? "자주 묻는 질문" : locale === "de" ? "Häufige Fragen" : locale === "pt" ? "Perguntas frequentes" : locale === "es" ? "Preguntas frecuentes" : locale === "fr" ? "Questions fréquentes" : "Frequently asked questions", items: d.faqs.map(({ q, a }) => ({ q, a })) },
  };
}
